class F{String s(boolean p,String x){if(!p)x=x.replace(" ","");var a=new java.util.Scanner(x).useDelimiter("\\D+").tokens().mapToLong(Long::parseLong).toArray();long r=1;for(int i=0;i<a.length/2;i++){long t=a[i],d=a[i+a.length/2],n=(long)Math.ceil((t-Math.sqrt(t*t-4.0*d))/2);r*=t-2*n+1;}return r+"";}}
